import { chromium } from "playwright";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUT_DIR = path.join(__dirname, "out");
const BASE = process.env.DEMO_URL ?? "http://127.0.0.1:5174";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function waitReady(page) {
  // Session chip shows a handle once sessions.start succeeded across regions.
  await page.waitForFunction(
    () => {
      const chips = [...document.querySelectorAll("button, span")];
      return chips.some((el) => /Locating|edge|Location unknown|🇺🇸|🇬🇧|🇩🇪|🇨🇦|🇦🇺|🇯🇵|🇸🇬|🇮🇳|🇧🇷|🇫🇷|NL|SE|IE/.test(el.textContent ?? ""));
    },
    { timeout: 30_000 },
  );
  // Wait until Insert is enabled (session ready + benches mounted).
  await page.getByRole("button", { name: /Insert \d+/ }).waitFor({ state: "visible", timeout: 30_000 });
  for (let i = 0; i < 40; i++) {
    const disabled = await page.getByRole("button", { name: /Insert \d+/ }).isDisabled();
    if (!disabled) return;
    await sleep(250);
  }
  throw new Error("Insert stayed disabled — sessions may not be ready");
}

async function waitInsertDone(page, timeoutMs = 90_000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const disabled = await page.getByRole("button", { name: /Insert \d+/ }).isDisabled();
    if (!disabled) return;
    await sleep(400);
  }
  throw new Error("Insert run did not finish in time");
}

async function main() {
  const browser = await chromium.launch({
    headless: true,
    args: ["--disable-dev-shm-usage"],
  });

  const context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    deviceScaleFactor: 2,
    recordVideo: {
      dir: OUT_DIR,
      size: { width: 1440, height: 900 },
    },
    colorScheme: "dark",
  });

  const page = await context.newPage();
  page.setDefaultTimeout(45_000);

  console.log(`Opening ${BASE}`);
  await page.goto(BASE, { waitUntil: "networkidle" });
  await sleep(1200); // let the hero settle on camera

  await waitReady(page);
  await sleep(800);

  // Smaller N so the demo finishes before viewers get bored.
  await page.getByRole("button", { name: /^10$/ }).click();
  await sleep(500);
  await page.getByRole("button", { name: "Insert 10" }).click();
  console.log("Running insert bench…");
  await waitInsertDone(page);
  await sleep(1800); // hold on the filled latency grid

  // Network tab
  await page.getByRole("button", { name: "Network test" }).click();
  await sleep(900);
  const runAll = page.getByRole("button", { name: /Run all regions|Testing/ });
  await runAll.click();
  console.log("Running network tests…");
  await page.getByRole("button", { name: "Run all regions" }).waitFor({ state: "visible", timeout: 120_000 });
  await sleep(1500);

  // Compare tab — chart from the earlier insert
  await page.getByRole("button", { name: "Compare" }).click();
  await sleep(2500);

  // Back to Latency for a clean closing frame
  await page.getByRole("button", { name: "Latency" }).click();
  await sleep(1800);

  const video = page.video();
  await page.close();
  const rawPath = video ? await video.path() : null;
  await context.close();
  await browser.close();

  if (!rawPath) {
    throw new Error("Playwright did not produce a video file");
  }

  // Rename to something shareable.
  const { renameSync, copyFileSync, existsSync, mkdirSync } = await import("node:fs");
  mkdirSync(OUT_DIR, { recursive: true });
  const finalWebm = path.join(OUT_DIR, "demo-regions.webm");
  if (existsSync(finalWebm)) {
    try {
      renameSync(finalWebm, path.join(OUT_DIR, `demo-regions-${Date.now()}.webm`));
    } catch {
      /* ignore */
    }
  }
  copyFileSync(rawPath, finalWebm);
  console.log(`Wrote ${finalWebm}`);
  console.log(`Raw Playwright path: ${rawPath}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

