/**
 * Smoke-test: Insert N=5 on the live UI and assert the primary median label
 * switches to server-span copy (list − add start).
 */
import { chromium } from "playwright";

const BASE = process.env.DEMO_URL ?? "http://127.0.0.1:5174";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function waitInsertEnabled(page) {
  await page.getByRole("button", { name: /Insert \d+/ }).waitFor({ state: "visible", timeout: 45_000 });
  for (let i = 0; i < 60; i++) {
    if (!(await page.getByRole("button", { name: /Insert \d+/ }).isDisabled())) return;
    await sleep(250);
  }
  throw new Error("Insert stayed disabled");
}

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(60_000);

await page.goto(BASE, { waitUntil: "networkidle" });
await waitInsertEnabled(page);

await page.getByRole("button", { name: /^1$/ }).click();
await sleep(300);
await page.getByRole("button", { name: "Insert 1" }).click();
await waitInsertEnabled(page);
await sleep(800);

const body = await page.locator("body").innerText();
const hasServerLabel = /median server span \(list − add start\)/.test(body);
const hasBrowserSecondary = /until browser saw it/.test(body);

console.log(hasServerLabel ? "OK: primary label is server span" : "FAIL: missing server span label");
console.log(hasBrowserSecondary ? "OK: browser E2E secondary shown" : "WARN: no browser secondary (maybe one region failed stamps)");

// Capture one big number for sanity
const nums = [...body.matchAll(/(\d+(?:\.\d+)?)\s*ms/g)].slice(0, 8).map((m) => m[0]);
console.log("sample ms values:", nums.join(", "));

await browser.close();
if (!hasServerLabel) process.exit(1);
